// Canonical source for Adam B2 English assessment activities.

export const adamB2QuickChallenges: Record<number, Exercise> = {
  1: { id: 'adam-b2-qc-1', type: 'multiple-choice', title: 'What Kind of Tale?', instructions: 'Choose the answer that matches the writer’s position in Chapter 1.', question: 'How does the writer describe the nature of Adam’s tale?', options: ['as a symbolic story that teaches morals through imagined events', 'as a factual tale with historical reality that also includes the Unseen', 'as a philosophical theory about good and evil rather than a real event'], correctAnswer: 1, explanation: 'The second paragraph says the tale “is not symbolic or imaginary, but it is an original factual tale with historical correctness and reality”, and adds that “it also includes the Unseen (al-ghayb)”.', feedback: { correct: 'Yes. The writer rejects a symbolic reading and calls the tale factual, while noting that it includes the Unseen.', incorrect: 'Read the first sentence of the second paragraph again. Look at the “not …, but …” structure: which reading does the writer reject, and which one does he choose?' } },
  2: { id: 'adam-b2-qc-2', type: 'true-false', title: 'Which Source Says What?', instructions: 'Decide whether the statement is true or false according to Chapter 2.', question: 'In Chapter 2, the information that people have different colours comes from the verse of Surah Sad.', correctAnswer: false, explanation: 'The verse of Surah Sad (71) says only that Allah created a human being “from clay”. The different colours (“white, red, black, and yellow”) come from the saying of Prophet Muhammad (pbuh) about the handful of dust. From this hadith the writer concludes that people “have no superiority over one another due to the difference in their colors.”', feedback: { correct: 'Correct. The verse is about clay; the colours come from the hadith, and the writer builds his conclusion on it.', incorrect: 'Compare the two sources. Read the verse at the end of the first paragraph, then the saying at the start of the second paragraph. Which one lists colours?' } },
  3: { id: 'adam-b2-qc-3', type: 'matching', matchingHeadings: { left: 'In the chapter', right: 'What it shows or tells us' }, title: 'Event and Meaning', instructions: 'Match each part of Chapter 3 with what the chapter says about it.', question: 'What does the chapter draw from each part of the account?', matchingPairs: [{ left: 'Allah breathed His spirit into Adam', right: 'the value Allah gave him, which sets him apart from other creatures' }, { left: 'The word “all” in “all the names”', right: 'how broad Adam’s understanding was' }, { left: 'The angels’ reply to Allah', right: 'they know only what Allah has taught them' }], correctAnswer: { 'Allah breathed His spirit into Adam': 'the value Allah gave him, which sets him apart from other creatures', 'The word “all” in “all the names”': 'how broad Adam’s understanding was', 'The angels’ reply to Allah': 'they know only what Allah has taught them' }, explanation: 'The first paragraph says breathing the spirit “shows the value that Allah gave him” and “distinguishes Adam (pbuh) from the rest of the creatures”. The last paragraph says “all the names” “points to the broadness of Adam (pbuh)’s knowledge”. In the verse the angels say, “We have no knowledge except what You have taught us.”', feedback: { correct: 'Well done. You separated what happened from what the writer says it shows.', incorrect: 'Check each part in its place: the spirit in the first paragraph, the angels’ words in the verse, and “all the names” in the last paragraph. What does the text say each one shows?' } },
  4: { id: 'adam-b2-qc-4', type: 'multiple-choice', title: 'Two Kinds of Knowledge', instructions: 'Choose the answer supported by Chapter 4.', question: 'According to the chapter, what does revelation help people understand?', options: ['how to maintain their life in this world', 'the names of all things on Earth', 'their role, their duty and the order established by Allah', 'why Satan was created from fire'], correctAnswer: 2, explanation: 'The chapter gives each kind of knowledge a different job: one “is necessary for mankind to maintain his worldly life, and revelation is essential to understand his role, duty, and the order established by Allah.” That is why the two “complete one another”.', feedback: { correct: 'Right. Revelation explains role, duty and divine order, while the other knowledge supports worldly life.', incorrect: 'Find the sentence in the second paragraph that begins “One is necessary for mankind …”. It gives one job to each kind of knowledge. Which job belongs to revelation?' } },
  5: { id: 'adam-b2-qc-5', type: 'multiple-choice', title: 'Answering Iblis', instructions: 'Choose the answer supported by Chapter 5.', question: 'Iblis claims he is better because of the material he was created from. What does the writer use to answer this claim?', options: ['the angels’ knowledge, which never changes', 'Adam’s humble origin, which shows that Allah does not focus on origins', 'the angels’ prostration, which was an act of worship', 'Adam’s wish to live forever in Paradise'], correctAnswer: 1, explanation: 'At the end of the chapter the writer says Iblis “underlines his superiority because of the material from which he was created, yet Adam (pbuh)’s humble origin shows that Allah does not focus on origins, that is, race, colour, or ethnicity, since all humans ultimately originate from dried mud.”', feedback: { correct: 'Yes. The writer turns Adam’s humble origin into evidence that origin, race and colour do not decide a person’s value.', incorrect: 'Read the last sentence of the chapter. After the word “yet”, what does the writer set against Iblis’s claim?' } },
  6: { id: 'adam-b2-qc-6', type: 'sequencing', title: 'From Challenge to Threat', instructions: 'Put the steps of Satan’s story in Chapter 6 in order.', question: 'How does Satan move from challenging his Creator to declaring his plan?', sequencingItems: [{ id: '1', text: 'Satan challenges his Creator.' }, { id: '2', text: 'Allah orders him to get out and calls him an outcast.' }, { id: '3', text: 'Satan asks for time until the Day people are raised up.' }, { id: '4', text: 'Allah gives him time until the Day of the Time Appointed.' }, { id: '5', text: 'Satan swears by Allah’s majesty that he will deceive them all.' }], correctAnswer: ['1', '2', '3', '4', '5'], explanation: 'The chapter says Satan “reached the point of no return by challenging his Creator”. The verses of Surah Sad (77–82) then show the steps: Allah expels and curses him, Satan asks to be allowed time, Allah grants it, and Satan swears, “By Your majesty, I will deceive them all.”', feedback: { correct: 'Well done. Satan’s threat comes only after he is expelled and given time.', incorrect: 'Follow the conversation in the verses of Surah Sad at the end of the chapter: who speaks first, what is asked for, and what is given?' } },
  7: { id: 'adam-b2-qc-7', type: 'multiple-choice', title: 'Satan’s Motive', instructions: 'Choose the reason given in Chapter 7.', question: 'Why did Satan want to remove Adam from Allah’s mercy?', options: ['He wanted to live forever in Paradise himself.', 'He saw Adam as the cause of his own expulsion from Allah’s mercy.', 'Adam had been given knowledge that Satan did not have.'], correctAnswer: 1, explanation: 'The first paragraph says Satan “would seek a way to remove Adam (pbuh) from mercy, because he thought of Adam (pbuh) as the cause of his expulsion from Allah’s mercy.”', feedback: { correct: 'Correct. The text gives Satan’s motive with “because”: he blamed Adam for his own expulsion.', incorrect: 'Look in the first paragraph for the sentence about Satan that contains “because”. What did Satan think about Adam?' } },
  8: { id: 'adam-b2-qc-8', type: 'multiple-choice', title: 'Why They Hurried', instructions: 'Choose the reason the writer gives in Chapter 8.', question: 'Why, according to the writer, were Adam and Eve in a hurry to cover themselves?', options: ['because the sense of shame (haya) is part of human nature', 'because Allah had called out to them', 'because they were afraid that Satan would see them'], correctAnswer: 0, explanation: 'The second paragraph explains: “They were in haste to hide their private parts, because the sense of shame (haya) is inborn human nature and nakedness is contrary to human nature.”', feedback: { correct: 'Yes. The writer explains their haste with the inborn sense of shame (haya).', incorrect: 'Read the end of the second paragraph. Find the sentence with “in haste” and read what follows “because”.' } },
  9: { id: 'adam-b2-qc-9', type: 'matching', matchingHeadings: { left: 'In the chapter', right: 'What it led to or means' }, title: 'From Regret to Prophethood', instructions: 'Match each part of Chapter 9 with what the chapter says about it.', question: 'How does the chapter link Adam’s regret, his forgiveness and his later role?', matchingPairs: [{ left: 'Adam’s deep regret', right: 'was the reason for Allah’s mercy upon him' }, { left: 'The words Adam received from his Lord', right: 'taught him how to ask for forgiveness' }, { left: 'A community emerged on Earth', right: 'Adam was given prophethood' }, { left: 'A person who makes a mistake', right: 'must look for the fault within himself and turn to Allah at once' }], correctAnswer: { 'Adam’s deep regret': 'was the reason for Allah’s mercy upon him', 'The words Adam received from his Lord': 'taught him how to ask for forgiveness', 'A community emerged on Earth': 'Adam was given prophethood', 'A person who makes a mistake': 'must look for the fault within himself and turn to Allah at once' }, explanation: 'The chapter says: “His regret itself was the reason for Allah’s mercy upon him”; Adam “received words from his Lord (to learn how to ask for forgiveness)”; “when a community emerged, Adam (pbuh) was given prophethood”; and humans “must recognize their mistakes, seek the fault within themselves, and immediately turn towards Allah.”', feedback: { correct: 'Well done. You followed the chapter from regret and forgiveness to prophethood and its lesson for all people.', incorrect: 'The first two parts are at the start of the chapter, near the verses. For the community, read about the time after the descent. The lesson for all people is in the last sentence.' } },
  10: { id: 'adam-b2-qc-10', type: 'true-false', title: 'Who Reports It?', instructions: 'Decide whether the statement is true or false according to Chapter 10.', question: 'In Chapter 10, Ibn Abbas is the one who reports that Adam descended on As-Safa and Eve on Al-Marwa.', correctAnswer: false, explanation: 'The chapter names two different sources. Ibn Abbas says Adam descended on the land “Dihna” between Mecca and Taif. It is Ibn Umar who “said that Adam (pbuh) descended on As-Safa and Eve on Al-Marwa”.', feedback: { correct: 'Correct. The report about As-Safa and Al-Marwa comes from Ibn Umar; Ibn Abbas speaks about Dihna.', incorrect: 'Look at the reports at the end of the chapter. Check which name is attached to Dihna and which name is attached to As-Safa and Al-Marwa.' } },
  11: { id: 'adam-b2-qc-11', type: 'multiple-choice', title: 'A Life Without Meaning', instructions: 'Choose the writer’s claim in Chapter 11.', question: 'According to the writer, what happens when Allah is removed from the human mind?', options: ['Human life loses its meaning and purpose.', 'People must work harder to keep themselves alive.', 'The battle between good and evil comes to an end.', 'Satan loses his power to deceive people.'], correctAnswer: 0, explanation: 'The third paragraph says: “Satan wants human beings not to remember Allah, yet the removal of Allah from the human mind means the removal of meaning and purpose from human life.”', feedback: { correct: 'Yes. For the writer, forgetting Allah takes away meaning and purpose; this is why Satan wants people to forget.', incorrect: 'Read the third paragraph again. Find the words “the removal of Allah from the human mind” and read to the end of that sentence.' } },
  12: { id: 'adam-b2-qc-12', type: 'multiple-choice', title: 'Two Offerings', instructions: 'Choose the reason given in Chapter 12.', question: 'Why, according to the chapter, was Qabil’s offering not accepted?', options: ['Adam had already decided that Habil was in the right.', 'Qabil was not sincere in his offering.', 'Grain was worth less than cattle.', 'Qabil had threatened his brother before the offering.'], correctAnswer: 1, explanation: 'The first paragraph says: “Habil offered his best cattle while Qabil offered his worst grain. Qabil’s sacrifice was not accepted by Allah because of his insincerity in his offering.” The threat comes after this, because the result angered Qabil.', feedback: { correct: 'Correct. The problem was Qabil’s insincerity, not the kind of offering: he gave his worst, while Habil gave his best.', incorrect: 'Read the sentences about the two offerings in the first paragraph. Look for “because of” to find the reason, and notice when the threat is made.' } },
  13: { id: 'adam-b2-qc-13', type: 'multiple-choice', title: 'Habil’s Hope', instructions: 'Choose the answer supported by Chapter 13.', question: 'Why did Habil speak to his brother at the end of the chapter?', options: ['He hoped to lessen the hatred in his brother.', 'He wanted to frighten his brother with his own strength.', 'He wanted Adam to judge between them.'], correctAnswer: 0, explanation: 'The chapter says Habil “did not want his brother to be hurt” and that, “hoping to lessen the hatred in his brother”, he advised him to repent and forget his threat.', feedback: { correct: 'Yes. Habil answered a threat with advice and compassion, not with a threat of his own.', incorrect: 'Read the last two sentences of the chapter. What did Habil hope for when he spoke to his brother?' } },
  14: { id: 'adam-b2-qc-14', type: 'sequencing', title: 'After the Request', instructions: 'Put the events of Chapter 14 in order.', question: 'What happened after Habil’s brotherly request?', sequencingItems: [{ id: '1', text: 'Habil’s request does not lessen the hatred in Qabil’s heart.' }, { id: '2', text: 'Qabil kills his brother.' }, { id: '3', text: 'Qabil carries the body from place to place, trying to hide it.' }, { id: '4', text: 'Two ravens fight, and one of them dies.' }, { id: '5', text: 'The other raven digs a hole and covers the dead raven.' }], correctAnswer: ['1', '2', '3', '4', '5'], explanation: 'The chapter begins: “This brotherly request did nothing to lessen the hatred in Qabil’s heart.” Then Qabil kills his brother. Not knowing what to do, he carries the body and tries to hide it. Finally Allah sends two ravens; one dies, and the other buries it.', feedback: { correct: 'Well done. The ravens appear only after Qabil has carried the body and does not know what to do.', incorrect: 'Follow Qabil through the chapter: the beginning (the request), the middle (what he does with the body) and the end (the ravens).' } },
  15: { id: 'adam-b2-qc-15', type: 'multiple-choice', title: 'Event or Interpretation?', instructions: 'Choose the sentence that is the writer’s interpretation.', question: 'Which sentence from Chapter 15 interprets the events instead of reporting them?', options: ['“Qabil then buried his brother.”', '“This was also the first burial of man.”', '“What is essentially being described here is the consequence of choosing evil.”', '“Adam (pbuh) prayed for his son …”'], correctAnswer: 2, explanation: 'The third paragraph starts a new step: after the events, the writer explains what they mean. “What is essentially being described here is the consequence of choosing evil.” The other sentences report what happened.', feedback: { correct: 'Correct. This sentence steps back from the events and says what they show.', incorrect: 'Three of these sentences tell us what someone did or what happened. Look at the start of the third paragraph for a sentence that explains what the story “essentially” describes.' } },
  16: { id: 'adam-b2-qc-16', type: 'matching', matchingHeadings: { left: 'Who', right: 'What Chapter 16 says' }, title: 'Adam’s Last Years', instructions: 'Match each name with what Chapter 16 says about it.', question: 'What does the chapter tell us about the people and beings in Adam’s last years?', matchingPairs: [{ left: 'Seth', right: 'was made successor and learned the hours of worship' }, { left: 'Iblis', right: 'Adam warned his children about him from his own experience' }, { left: 'The later prophets', right: 'would have different names and miracles but one call' }, { left: 'The Angel of Death', right: 'when Adam recognized him, his heart filled with peace' }], correctAnswer: { 'Seth': 'was made successor and learned the hours of worship', 'Iblis': 'Adam warned his children about him from his own experience', 'The later prophets': 'would have different names and miracles but one call', 'The Angel of Death': 'when Adam recognized him, his heart filled with peace' }, explanation: 'Adam “told them about Iblis and warned them by telling them about his own experience”; he “appointed his son Seth to be his successor and taught him the hours of the day and night with their appropriate acts of worship”; the prophets “would have different names and miracles, but they would be united in one thing”; and “when he recognized the Angel of Death among them, his heart filled with peace.”', feedback: { correct: 'Well done. You traced Adam’s warning, his successor, his promise about the prophets and his peaceful death.', incorrect: 'Iblis is in the first paragraph. Seth appears where Adam’s death “drew near”. The prophets and the Angel of Death are in the second paragraph.' } },
  17: { id: 'adam-b2-qc-17', type: 'multiple-choice', title: 'Satan’s Real Strength', instructions: 'Choose the writer’s claim in Chapter 17.', question: 'According to the writer, what makes Satan look so strong?', options: ['his authority over every human being', 'his rebellion against Allah', 'the fire from which he was created', 'human weakness, lack of morals and lack of carefulness'], correctAnswer: 3, explanation: 'The writer says: “Satan alone is not strong; it is only man’s weakness and lack of morals and carefulness that make Satan look so strong.” In the verses Allah says: “Over My servants you have no authority, except for the sinners who follow you.”', feedback: { correct: 'Yes. The writer places the problem in human weakness, so people are responsible for their choices.', incorrect: 'Find the sentence that begins “Satan alone is not strong …”. What does the writer say makes him look strong? Check the verses, too: does Satan have authority over everyone?' } },
};

export const adamB2KnowledgeCheckExercises: Exercise[] = [
  { id: 'adam-b2-kc-1-hidden-arrogance', type: 'multiple-choice', title: 'A Hidden Arrogance', instructions: 'Choose the best reading of the writer’s word choice in Chapter 5.', question: 'The writer calls Iblis’s arrogance “unapparent” until Adam appeared. What does this word choice suggest?', options: ['Adam’s creation revealed an arrogance already inside Iblis.', 'Iblis became arrogant only after Adam was made from clay.', 'The angels also felt proud until Adam told them the names.', 'Iblis hid his arrogance from Allah but not from the angels.'], correctAnswer: 0, explanation: 'Chapter 5: “Satan’s—in other words, Iblis’—unapparent arrogance came to the surface when Adam (pbuh) appeared on the scene.” The same paragraph says this arrogance “came from his belief that his origin was superior to Adam (pbuh)’s.”', feedback: { correct: 'Well read. “Unapparent” means the arrogance was there but not yet visible; Adam’s appearance brought it “to the surface” rather than creating it.', incorrect: 'Look closely at “unapparent” and “came to the surface” in the second paragraph of Chapter 5. Was the arrogance new, or was it already there?' } },
  { id: 'adam-b2-kc-2-two-responses', type: 'multiple-choice', title: 'Two Responses', instructions: 'Compare the two chapters and choose the best answer.', question: 'Compare Iblis’s words in Chapter 4 with Adam and Eve’s words in Chapter 9. What is the key difference?', options: ['Iblis asks for time to repent; they ask to stay in Paradise.', 'Iblis defends himself as better; they admit wronging themselves.', 'Both admit a mistake, but only Adam and Eve are forgiven.', 'Iblis blames his fire; Adam and Eve blame Satan’s whisper.'], correctAnswer: 1, explanation: 'Chapter 4: “I am better than he (Adam); You created me from fire, and You created him from clay.” Chapter 9: “Our Lord, we have done wrong to ourselves. Unless You forgive us, and have mercy on us, we will be among the losers.”', feedback: { correct: 'Exactly. Iblis argues for his own superiority, while Adam and Eve look for the fault within themselves and turn to Allah. The book presents this as the way to remain an honoured human.', incorrect: 'Find the words Iblis says at the end of Chapter 4 and the words Adam and Eve say in the first verse of Chapter 9. Who defends himself, and who blames himself?' } },
  { id: 'adam-b2-kc-3-years-of-whispering', type: 'true-false', title: 'The Slow Temptation', instructions: 'Decide whether the statement is true or false according to Chapter 7.', question: 'Adam and Eve ate from the tree the first time Satan whispered to them.', correctAnswer: false, explanation: 'Chapter 7: “He started to whisper to them day after day, trying to persuade both.” Later: “Years went by, and Adam (pbuh) and Eve were preoccupied with thoughts of that tree. Then one day, they decided to eat of its fruit.”', feedback: { correct: 'Right, the statement is false. Satan whispered “day after day”, and years passed before they decided to eat. The temptation worked slowly, through Adam’s forgetfulness and weakening determination.', incorrect: 'Reread the end of the first paragraph and the middle of the last paragraph of Chapter 7. How long did the whispering go on before they ate?' } },
  { id: 'adam-b2-kc-4-lesson-of-paradise', type: 'multiple-choice', title: 'What the Experience Taught', instructions: 'Choose the answer supported by Chapter 10.', question: 'According to Chapter 10, what was the experience in Paradise meant to teach Adam, Eve and their offspring?', options: ['that the names alone are enough to guide every part of human life', 'that Paradise can be won back by working hard on the Earth', 'that Satan is their enemy and the Creator’s word is the right path', 'that angels and humans share exactly the same kind of knowledge'], correctAnswer: 2, explanation: 'Chapter 10: “It was meant to teach Adam (pbuh), Eve, and their offspring the knowledge that Satan is their enemy and that the right path is to act in accordance with what they have heard from the Creator.”', feedback: { correct: 'Yes. The writer calls the experience “a cornerstone of their vicegerency”: it taught who the enemy is and whose word to follow.', incorrect: 'Read the first paragraph of Chapter 10 again. Find the sentence that begins “It was meant to teach …”.' } },
  { id: 'adam-b2-kc-5-what-eased-grief', type: 'true-false', title: 'Adam’s Grief on Earth', instructions: 'Decide whether the statement is true or false according to Chapter 11.', question: 'The writer says that nothing on Earth could ease Adam’s grief.', correctAnswer: false, explanation: 'Chapter 11: “The only thing that eased his grief was that he was master of the Earth and had to govern it. He had to maintain, cultivate, construct, and populate the Earth.”', feedback: { correct: 'Right, the statement is false. One thing eased his grief: his role as master of the Earth, with the duty to govern and build it.', incorrect: 'Reread the last paragraph of Chapter 11. The writer names one thing that eased Adam’s grief. What was it?' } },
  { id: 'adam-b2-kc-6-told-simply', type: 'multiple-choice', title: 'A Story Told Simply', instructions: 'Choose the reason the writer gives in Chapter 12.', question: 'Chapter 12 says the Qur’an tells the story of the two sons “in a simple manner”. What reason does the writer give?', options: ['The Torah had already given every detail of it.', 'The brothers’ names were not known at that time.', 'The killing was too painful to describe in full.', 'Only the wisdom of the story needs to be known.'], correctAnswer: 3, explanation: 'Chapter 12: “It does not openly mention any of the details found in the Torah, as, according to the Qur’an, the only thing that needs to be known is the wisdom of the story.”', feedback: { correct: 'Correct. The Qur’an leaves out names and details because its aim is the lesson, not the full record of events.', incorrect: 'Read the last paragraph of Chapter 12. Find the word “as” after “details found in the Torah”: what reason follows it?' } },
  { id: 'adam-b2-kc-7-at-first-glance', type: 'multiple-choice', title: '“At First Glance”', instructions: 'Choose the point the writer is making in Chapter 13.', question: 'The writer says Qabil’s attitude “may seem unacceptable” only “at first glance”. What point is the writer preparing?', options: ['Qabil’s anger was fair because his offering was refused.', 'Qabil was not responsible, since Satan controlled him.', 'Habil should have defended himself more strongly.', 'Every human can be jealous or selfish, so the test is ours too.'], correctAnswer: 3, explanation: 'Chapter 13: “At first glance, Qabil’s rebellious attitude may seem unacceptable. However, it is important to remember that humans have the potential for both good and evil.” And: “Thus, Allah tests us through our dual nature.”', feedback: { correct: 'Well done. The writer does not excuse Qabil. He asks readers to see the same potential for evil in themselves, because controlling it is everyone’s test.', incorrect: 'Read what comes right after “However” in the middle of Chapter 13. Is the writer excusing Qabil, or turning the lesson towards the reader?' } },
  { id: 'adam-b2-kc-8-enemy-of-humans', type: 'true-false', title: 'The Real Rival', instructions: 'Decide whether the statement is true or false according to Chapters 1 and 17.', question: 'Chapters 1 and 17 both present Satan above all as an enemy of human beings, not only as a rebel against Allah.', correctAnswer: true, explanation: 'Chapter 1: “Satan is portrayed as a rebel against Allah’s command but also as a rival and enemy of Adam (pbuh) rather than Allah.” Chapter 17: the Qur’an “does not focus so much on Satan’s anti-God position” but “rather underlines his anti-human attitude”.', feedback: { correct: 'Right, the statement is true. The book opens and closes with the same idea: Satan did rebel, but his main target is the human being.', incorrect: 'Compare the last sentence of the first paragraph of Chapter 1 with the second paragraph of Chapter 17. Whom does Satan mainly oppose there?' } },
];

